export interface AttackTactic {
  id: string;
  name: string;
}

export interface AttackTechnique {
  id: string;
  name: string;
  tactics: AttackTactic[];
}

let cache: AttackTechnique[] | null = null;

/**
 * Lazy-loads the bundled ATT&CK technique dataset (generated by
 * scripts/generate-attack-dataset.mjs, ~100KB). The dynamic import lets Vite
 * split it out of the main bundle; it loads on first autocomplete use.
 */
export async function loadTechniques(): Promise<AttackTechnique[]> {
  if (!cache) {
    const module = await import('./attack-techniques.json');
    cache = module.default as AttackTechnique[];
  }
  return cache;
}

/**
 * Substring search over id and name, prefix matches ranked first
 * (so "T10" lists T1003 before T1110, and "valid" puts "Valid Accounts" on top).
 */
export function searchTechniques(
  techniques: AttackTechnique[],
  query: string,
  limit = 50
): AttackTechnique[] {
  const q = query.trim().toLowerCase();
  if (!q) return techniques.slice(0, limit);

  const prefix: AttackTechnique[] = [];
  const substring: AttackTechnique[] = [];
  for (const technique of techniques) {
    const id = technique.id.toLowerCase();
    const name = technique.name.toLowerCase();
    if (id.startsWith(q) || name.startsWith(q)) {
      prefix.push(technique);
    } else if (id.includes(q) || name.includes(q)) {
      substring.push(technique);
    }
    if (prefix.length >= limit) break;
  }
  return [...prefix, ...substring].slice(0, limit);
}
